  const items = [
    { id: "__proto__", n: 1 },
    { id: "toString", n: 2 },
    { id: "__proto__", n: 3 },
    { id: "constructor", n: 4 },
    { id: "toString", n: 5 },
  ];
  assert.deepEqual(uniqueBy(items, byId), [
    { id: "__proto__", n: 1 },
    { id: "toString", n: 2 },
    { id: "constructor", n: 4 },
  ]);
});

function uniqueBy(items, keyOf) {
  const seen = new Set();
  const result = [];
  for (const item of items) {
    const key = keyOf(item);
    if (seen.has(key)) {
      continue;
    }
    seen.add(key);
    result.push(item);
  }
  return result;
}

module.exports = { uniqueBy };

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { uniqueBy } = require('../src/solution.cjs');

const identity = (x) => x;

test('keeps the first item for each duplicate key in input order', () => {
  const items = [
    { id: 2, name: 'b1' },
    { id: 1, name: 'a1' },
    { id: 2, name: 'b2' },
    { id: 3, name: 'c1' },
    { id: 1, name: 'a2' },
  ];

  assert.deepEqual(uniqueBy(items, (item) => item.id), [
    { id: 2, name: 'b1' },
    { id: 1, name: 'a1' },
    { id: 3, name: 'c1' },
  ]);
});

test('distinguishes number 1 from string "1"', () => {
  const items = [
    { k: 1, n: 'num' },
    { k: '1', n: 'str' },
    { k: 1, n: 'num-dup' },
    { k: '1', n: 'str-dup' },
  ];

  assert.deepEqual(uniqueBy(items, (item) => item.k), [
    { k: 1, n: 'num' },
    { k: '1', n: 'str' },
  ]);
});

test('handles mixed primitive keys', () => {
  assert.deepEqual(uniqueBy([1, '1', 1, '1', 0, '0', 0], identity), [1, '1', 0, '0']);
});

test('treats "__proto__" and other prototype names as ordinary keys', () => {
  const items = ['__proto__', 'constructor', 'toString', '__proto__', 'constructor'];

  assert.deepEqual(uniqueBy(items, identity), ['__proto__', 'constructor', 'toString']);
});

test('returns an empty array for empty input', () => {
  assert.deepEqual(uniqueBy([], identity), []);
});

test('returns a new array and does not mutate the input', () => {
  const items = [3, 1, 3, 2, 1];
  const snapshot = [...items];

  const result = uniqueBy(items, identity);

  assert.notEqual(result, items);
  assert.deepEqual(result, [3, 1, 2]);
  assert.deepEqual(items, snapshot);
});

