            merge_intervals([[1, 2], [2, 3], [3, 4], [4, 5]]), [[1, 5]]
        )

    def test_input_is_not_mutated(self):
        intervals = [[8, 10], [1, 3], [2, 6]]
        snapshot = [list(pair) for pair in intervals]
        merge_intervals(intervals)
        self.assertEqual(intervals, snapshot)

    def test_nested_pairs_are_not_mutated(self):
        inner = [1, 10]
        intervals = [inner, [2, 3]]
        result = merge_intervals(intervals)
        self.assertEqual(inner, [1, 10])
        self.assertEqual(result, [[1, 10]])
        self.assertIsNot(result[0], inner)

