def merge_intervals(intervals):
    """Merge closed integer intervals; return new sorted, nonoverlapping [start, end] pairs.

    Runs in O(n log n) time and O(n) extra space. The input and its pairs are not mutated.
    """
    merged = []
    for start, end in sorted(intervals, key=lambda pair: pair[0]):
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged

