def brute_force(intervals):
    points = set()
    for start, end in intervals:
        points.update(range(start, end + 1))
    if not points:
        return []
    result = []
    run_start = prev = None
    for p in sorted(points):
        if run_start is None:
            run_start = prev = p
        elif p == prev + 1:
            prev = p
        else:
            result.append([run_start, prev])
            run_start = prev = p
    result.append([run_start, prev])
    return result


