def brute_force(intervals):
    # Doubled grid: even cells are integer points, odd cells are open gaps between them.
    cells = set()
    for start, end in intervals:
        cells.update(range(2 * start, 2 * end + 1))
    if not cells:
        return []
    result = []
    run_start = prev = None
    for c in sorted(cells):
        if run_start is None:
            run_start = prev = c
        elif c == prev + 1:
            prev = c
        else:
            result.append([run_start // 2, prev // 2])
            run_start = prev = c
    result.append([run_start // 2, prev // 2])
    return result

