async function mapLimit(items, limit, fn) {
  if (!Number.isInteger(limit) || limit < 1) {
    throw new RangeError('limit must be a positive integer');
  }

  const results = new Array(items.length);
  let next = 0;
  let failed = false;

  async function worker() {
    while (!failed && next < items.length) {
      const index = next++;
      try {
        results[index] = await fn(items[index]);
      } catch (error) {
        failed = true;
        throw error;
      }
    }
  }

  const workerCount = Math.min(limit, items.length);
  await Promise.all(Array.from({ length: workerCount }, worker));
  return results;
}

module.exports = { mapLimit };

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { mapLimit } = require('../src/solution.cjs');

function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

// Lets all pending microtasks run; mapLimit only uses promise continuations.
function flush() {
  return new Promise((resolve) => setImmediate(resolve));
}

function controlledFn() {
  const calls = [];
  const fn = (item) => {
    const call = { item, d: deferred() };
    calls.push(call);
    return call.d.promise;
  };
  return { calls, fn };
}

test('returns results in input order when calls finish out of order', async () => {
  const { calls, fn } = controlledFn();
  const pending = mapLimit(['a', 'b', 'c'], 3, fn);
  await flush();

  assert.deepEqual(calls.map((c) => c.item), ['a', 'b', 'c']);
  calls[2].d.resolve('C');
  calls[0].d.resolve('A');
  calls[1].d.resolve('B');

  assert.deepEqual(await pending, ['A', 'B', 'C']);
});

test('never runs more than limit calls at once and starts new ones as slots free', async () => {
  const { calls, fn } = controlledFn();
  const pending = mapLimit([0, 1, 2, 3, 4], 2, fn);
  await flush();
  assert.deepEqual(calls.map((c) => c.item), [0, 1]);

  calls[1].d.resolve('r1');
  await flush();
  assert.deepEqual(calls.map((c) => c.item), [0, 1, 2]);

  calls[0].d.resolve('r0');
  await flush();
  assert.deepEqual(calls.map((c) => c.item), [0, 1, 2, 3]);

  calls[3].d.resolve('r3');
  calls[2].d.resolve('r2');
  await flush();
  assert.deepEqual(calls.map((c) => c.item), [0, 1, 2, 3, 4]);

  calls[4].d.resolve('r4');
  assert.deepEqual(await pending, ['r0', 'r1', 'r2', 'r3', 'r4']);
});

test('limit larger than input starts every call immediately', async () => {
  const { calls, fn } = controlledFn();
  const pending = mapLimit([1, 2], 10, fn);
  await flush();
  assert.equal(calls.length, 2);

  calls[0].d.resolve('x');
  calls[1].d.resolve('y');
  assert.deepEqual(await pending, ['x', 'y']);
});

test('empty input resolves to [] without calling fn', async () => {
  let called = false;
  const result = await mapLimit([], 3, () => {
    called = true;
  });
  assert.deepEqual(result, []);
  assert.equal(called, false);
});

test('accepts synchronous return values', async () => {
  const result = await mapLimit([1, 2, 3], 1, (n) => n * 10);
  assert.deepEqual(result, [10, 20, 30]);
});

for (const limit of [0, -1, 1.5, NaN, Infinity, '2', undefined, null]) {
  test(`rejects with RangeError for invalid limit ${String(limit)}`, async () => {
    const { calls, fn } = controlledFn();
    await assert.rejects(mapLimit([1, 2], limit, fn), RangeError);
    await assert.rejects(mapLimit([], limit, fn), RangeError);
    assert.equal(calls.length, 0);
  });
}

test('rejects when a call rejects while other calls are still in flight', async () => {
  const { calls, fn } = controlledFn();
  const boom = new Error('boom');
  const outcome = assert.rejects(mapLimit([1, 2, 3], 2, fn), boom);
  await flush();

  calls[0].d.reject(boom);
  await outcome;
});

test('does not launch new calls after a failure, but lets in-flight calls finish', async () => {
  const { calls, fn } = controlledFn();
  const boom = new Error('boom');
  const outcome = assert.rejects(mapLimit([1, 2, 3, 4], 2, fn), boom);
  await flush();
  assert.equal(calls.length, 2);

  calls[0].d.reject(boom);
  await outcome;

  calls[1].d.resolve('still finishes');
  await flush();
  assert.equal(calls.length, 2);
});

test('rejects when fn throws synchronously', async () => {
  const boom = new Error('sync boom');
  const started = [];
  await assert.rejects(
    mapLimit([1, 2, 3], 1, (item) => {
      started.push(item);
      throw boom;
    }),
    boom,
  );
  assert.deepEqual(started, [1]);
});

async function mapLimit(items, limit, fn) {
  if (!Number.isInteger(limit) || limit < 1) {
    throw new RangeError(`limit must be a positive integer, got ${limit}`);
  }

  const results = new Array(items.length);
  let nextIndex = 0;
  let failed = false;

  async function worker() {
    while (!failed && nextIndex < items.length) {
      const index = nextIndex++;
      try {
        results[index] = await fn(items[index], index);
      } catch (error) {
        failed = true;
        throw error;
      }
    }
  }

  const workerCount = Math.min(limit, items.length);
  const workers = [];
  for (let i = 0; i < workerCount; i++) {
    workers.push(worker());
  }

  await Promise.all(workers);
  return results;
}

module.exports = { mapLimit };

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { mapLimit } = require('../src/solution.cjs');

// Lets all pending promise callbacks run before the next assertion.
const flush = () => new Promise((resolve) => setImmediate(resolve));

function controlledFn() {
  const calls = [];
  const fn = (item, index) => {
    const call = { item, index, settled: false };
    call.promise = new Promise((resolve, reject) => {
      call.resolve = resolve;
      call.reject = reject;
    });
    const markSettled = () => {
      call.settled = true;
    };
    call.promise.then(markSettled, markSettled);
    calls.push(call);
    return call.promise;
  };
