async function mapLimit(items, limit, fn) {
  if (!Number.isInteger(limit) || limit < 1) {
    throw new RangeError('limit must be a positive integer');
  }

  const list = Array.from(items);
  const results = new Array(list.length);
  let nextIndex = 0;
  let failed = false;

  async function worker() {
    while (!failed && nextIndex < list.length) {
      const index = nextIndex++;
      try {
        results[index] = await fn(list[index], index);
      } catch (error) {
        failed = true;
        throw error;
      }
    }
  }

  await Promise.all(Array.from({ length: Math.min(limit, list.length) }, worker));
  return results;
}

module.exports = { mapLimit };

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { mapLimit } = require('../src/solution.cjs');

// Drains pending microtasks so promise chains advance; no timing involved.
const flush = () => new Promise((resolve) => setImmediate(resolve));

function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

function controlledCalls() {
  const calls = [];
  let active = 0;
  let maxActive = 0;
  const fn = () => {
    const call = deferred();
    calls.push(call);
    active++;
    maxActive = Math.max(maxActive, active);
    return call.promise.finally(() => {
      active--;
    });
  };
  return { fn, calls, maxActive: () => maxActive };
}

