async function mapLimit(items, limit, fn) {
  if (!Number.isInteger(limit) || limit < 1) {
    throw new RangeError(`limit must be a positive integer, got ${limit}`);
  }

  const list = Array.from(items);
  if (list.length === 0) {
    return [];
  }

  return new Promise((resolve, reject) => {
    const results = new Array(list.length);
    let nextIndex = 0;
    let completed = 0;
    let failed = false;

    const startNext = () => {
      if (failed || nextIndex >= list.length) {
        return;
      }
      const index = nextIndex++;
      let pending;
      try {
        pending = Promise.resolve(fn(list[index], index));
      } catch (error) {
        pending = Promise.reject(error);
      }
      pending.then(
        (value) => {
          if (failed) {
            return;
          }
          results[index] = value;
          completed++;
          if (completed === list.length) {
            resolve(results);
          } else {
            startNext();
          }
        },
        (error) => {
          if (failed) {
            return;
          }
          failed = true;
          reject(error);
        },
      );
    };

    const initial = Math.min(limit, list.length);
    for (let i = 0; i < initial; i++) {
      startNext();
    }
  });
}

