const { test } = require('node:test');
const assert = require('node:assert/strict');
const { mapLimit } = require('../src/solution.cjs');

function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

// Drains all pending microtasks; deterministic, not time-based.
function settle() {
  return new Promise((resolve) => setImmediate(resolve));
}

function controlledFn() {
  const calls = [];
  const fn = (item, index) => {
    const d = deferred();
    calls.push({ item, index, ...d });
    return d.promise;
  };
  return { fn, calls };
}

