'use strict';

async function retry(operation, { attempts, delayMs, sleep, shouldRetry }) {
  if (!Number.isInteger(attempts) || attempts < 1) {
    throw new RangeError('attempts must be a positive integer');
  }

  for (let attempt = 1; ; attempt += 1) {
    try {
      return await operation();
    } catch (error) {
      if (attempt >= attempts || !shouldRetry(error)) {
        throw error;
      }
      await sleep(delayMs);
    }
  }
}

module.exports = { retry };

'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { retry } = require('../src/solution.cjs');

function fakeSleep() {
  const delays = [];
  const sleep = async (ms) => {
    delays.push(ms);
  };
  return { sleep, delays };
}

function failingThenSucceeding(failures, value) {
  let calls = 0;
  const operation = async () => {
    calls += 1;
    if (calls <= failures) {
      throw new Error(`fail ${calls}`);
    }
    return value;
  };
  return { operation, calls: () => calls };
}

test('returns first value without sleeping when operation succeeds immediately', async () => {
  const { sleep, delays } = fakeSleep();
  const { operation, calls } = failingThenSucceeding(0, 'ok');

  const result = await retry(operation, { attempts: 3, delayMs: 50, sleep, shouldRetry: () => true });

  assert.equal(result, 'ok');
  assert.equal(calls(), 1);
  assert.deepEqual(delays, []);
});

test('retries until success and sleeps only between attempts', async () => {
  const { sleep, delays } = fakeSleep();
  const { operation, calls } = failingThenSucceeding(2, 'third time');

  const result = await retry(operation, { attempts: 5, delayMs: 25, sleep, shouldRetry: () => true });

  assert.equal(result, 'third time');
  assert.equal(calls(), 3);
  assert.deepEqual(delays, [25, 25]);
});

test('throws the last error object unchanged after exhausting attempts', async () => {
  const { sleep, delays } = fakeSleep();
  const errors = [];
  let calls = 0;
  const operation = async () => {
    calls += 1;
    const error = new Error(`attempt ${calls}`);
    errors.push(error);
    throw error;
  };

  await assert.rejects(
    retry(operation, { attempts: 3, delayMs: 10, sleep, shouldRetry: () => true }),
    (error) => error === errors[2],
  );
  assert.equal(calls, 3);
  assert.deepEqual(delays, [10, 10]);
});

test('attempts of 1 calls once, never sleeps, and rethrows the error', async () => {
  const { sleep, delays } = fakeSleep();
  const failure = new Error('only try');
  let calls = 0;

  await assert.rejects(
    retry(async () => {
      calls += 1;
      throw failure;
    }, { attempts: 1, delayMs: 10, sleep, shouldRetry: () => true }),
    (error) => error === failure,
  );
  assert.equal(calls, 1);
  assert.deepEqual(delays, []);
});

test('does not retry when shouldRetry returns false', async () => {
  const { sleep, delays } = fakeSleep();
  const failure = new Error('fatal');
  let calls = 0;
  const seen = [];

  await assert.rejects(
    retry(async () => {
      calls += 1;
      throw failure;
    }, {
      attempts: 5,
      delayMs: 10,
      sleep,
      shouldRetry: (error) => {
        seen.push(error);
        return false;
      },
    }),
    (error) => error === failure,
