async function retry(
  operation,
  {
    attempts,
    delayMs = 0,
    sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
    shouldRetry = () => true,
  } = {},
) {
  if (!Number.isInteger(attempts) || attempts < 1) {
    throw new RangeError('attempts must be a positive integer');
  }

  for (let attempt = 1; ; attempt += 1) {
    try {
      return await operation();
    } catch (error) {
      if (attempt >= attempts || !shouldRetry(error)) {
        throw error;
      }
      await sleep(delayMs);
    }
  }
}

module.exports = { retry };

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { retry } = require('../src/solution.cjs');

function fakeSleep() {
  const calls = [];
  const sleep = async (ms) => {
    calls.push(ms);
  };
  return { sleep, calls };
}

function failingThenSucceeding(failures, value = 'ok') {
  let calls = 0;
  const operation = async () => {
    calls += 1;
    if (calls <= failures) {
      throw new Error(`fail ${calls}`);
    }
    return value;
  };
  return { operation, count: () => calls };
}

test('returns the first successful value without sleeping', async () => {
  const { sleep, calls } = fakeSleep();
  const op = failingThenSucceeding(0, 42);

  const result = await retry(op.operation, { attempts: 3, delayMs: 10, sleep });

  assert.equal(result, 42);
  assert.equal(op.count(), 1);
  assert.deepEqual(calls, []);
});

test('retries until success and sleeps only between failed attempts', async () => {
  const { sleep, calls } = fakeSleep();
  const op = failingThenSucceeding(2, 'done');

  const result = await retry(op.operation, { attempts: 5, delayMs: 25, sleep });

  assert.equal(result, 'done');
  assert.equal(op.count(), 3);
  assert.deepEqual(calls, [25, 25]);
});

test('sleep runs after a failure and before the next attempt', async () => {
  const events = [];
  let calls = 0;
  const operation = async () => {
    calls += 1;
    events.push(`op${calls}`);
    if (calls < 3) throw new Error('boom');
    return 'ok';
  };
  const sleep = async (ms) => {
    events.push(`sleep${ms}`);
  };

  await retry(operation, { attempts: 3, delayMs: 7, sleep });

  assert.deepEqual(events, ['op1', 'sleep7', 'op2', 'sleep7', 'op3']);
});

test('after exhaustion throws the last error object unchanged and does not sleep after the final failure', async () => {
  const { sleep, calls } = fakeSleep();
  const errors = [];
  let attempt = 0;
  const operation = async () => {
    attempt += 1;
    const error = new Error(`attempt ${attempt}`);
    error.attempt = attempt;
    errors.push(error);
    throw error;
  };

  await assert.rejects(
    retry(operation, { attempts: 3, delayMs: 5, sleep }),
    (error) => {
      assert.strictEqual(error, errors[2]);
      assert.equal(error.attempt, 3);
      return true;
    },
  );

