def topological_order(
    nodes: Sequence[str], edges: Iterable[tuple[str, str]]
) -> list[str]:
    successors: dict[str, dict[str, None]] = {node: {} for node in nodes}
    indegree: dict[str, int] = {node: 0 for node in nodes}
    for before, after in edges:
        if after not in successors[before]:
            successors[before][after] = None
            indegree[after] += 1

    ready = deque(node for node in nodes if indegree[node] == 0)
    order: list[str] = []
    while ready:
        node = ready.popleft()
        order.append(node)
        for after in successors[node]:
            indegree[after] -= 1
            if indegree[after] == 0:
                ready.append(after)

    if len(order) != len(nodes):
        raise ValueError("graph contains a cycle")
    return order

