import os
import sqlite3
import sys
import unittest

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))

from solution import search  # noqa: E402


class SearchTests(unittest.TestCase):
    def setUp(self):
        self.conn = sqlite3.connect(":memory:")
        self.conn.execute("CREATE TABLE users (id INTEGER, name TEXT)")
        rows = [
            (1, "alice"),
            (2, "albert"),
            (3, "50% off"),
            (4, "500 units"),
            (5, "a_b"),
            (6, "ab"),
            (7, "a\\b"),
            (8, "ax"),
            (9, "O'Brien"),
            (10, "bob"),
            (11, "bob"),
        ]
        self.conn.executemany("INSERT INTO users VALUES (?, ?)", rows)

    def tearDown(self):
        self.conn.close()

    def test_prefix_match_returns_id_and_name(self):
        self.assertEqual(search(self.conn, "al", 10), [(2, "albert"), (1, "alice")])

    def test_percent_is_literal(self):
        self.assertEqual(search(self.conn, "50%", 10), [(3, "50% off")])

    def test_underscore_is_literal(self):
        self.assertEqual(search(self.conn, "a_", 10), [(5, "a_b")])

    def test_backslash_is_literal(self):
        self.assertEqual(search(self.conn, "a\\", 10), [(7, "a\\b")])

    def test_quote_and_injection_text_is_inert(self):
        self.assertEqual(search(self.conn, "O'", 10), [(9, "O'Brien")])
        self.assertEqual(search(self.conn, "x' OR '1'='1", 10), [])

    def test_empty_prefix_matches_all_in_order(self):
        result = search(self.conn, "", 100)
        self.assertEqual(len(result), 11)
        self.assertEqual(result, sorted(result, key=lambda r: (r[1], r[0])))

    def test_ties_sorted_by_id(self):
        self.assertEqual(search(self.conn, "bob", 10), [(10, "bob"), (11, "bob")])

    def test_limit_zero_clamps_to_one(self):
        self.assertEqual(len(search(self.conn, "", 0)), 1)

    def test_negative_limit_clamps_to_one(self):
        self.assertEqual(len(search(self.conn, "", -5)), 1)

    def test_large_limit_clamps_to_100(self):
        for i in range(200):
            self.conn.execute("INSERT INTO users VALUES (?, ?)", (1000 + i, "bulk"))
        self.assertEqual(len(search(self.conn, "bulk", 1000)), 100)

    def test_bool_limit_rejected(self):
        with self.assertRaises(ValueError):
            search(self.conn, "", True)
        with self.assertRaises(ValueError):
            search(self.conn, "", False)

    def test_non_int_limit_rejected(self):
        for bad in ("5", 5.0, None, [5]):
            with self.subTest(limit=bad):
                with self.assertRaises(ValueError):
                    search(self.conn, "", bad)

    def test_non_str_prefix_rejected(self):
        with self.assertRaises(TypeError):
            search(self.conn, None, 5)


if __name__ == "__main__":
