from solution import search


class SearchTests(unittest.TestCase):
    def setUp(self):
        self.conn = sqlite3.connect(":memory:")
        self.conn.execute("CREATE TABLE users (id INTEGER, name TEXT)")

    def tearDown(self):
        self.conn.close()

    def add(self, rows):
        self.conn.executemany("INSERT INTO users (id, name) VALUES (?, ?)", rows)

    def names(self, prefix, limit=100):
        return [name for _, name in search(self.conn, prefix, limit)]

    def test_matches_prefix_and_orders_by_name_then_id(self):
        self.add([(3, "bob"), (1, "alice"), (2, "albert"), (4, "alice"), (5, "carol")])
        self.assertEqual(search(self.conn, "al", 10), [(2, "albert"), (1, "alice"), (4, "alice")])

    def test_percent_in_prefix_is_literal(self):
        self.add([(1, "50% off"), (2, "500 off"), (3, "50 off")])
        self.assertEqual(self.names("50%"), ["50% off"])

    def test_underscore_in_prefix_is_literal(self):
        self.add([(1, "a_c"), (2, "abc")])
        self.assertEqual(self.names("a_"), ["a_c"])

    def test_backslash_in_prefix_is_literal(self):
        self.add([(1, "a\\b"), (2, "ab")])
        self.assertEqual(self.names("a\\"), ["a\\b"])

    def test_sql_injection_is_treated_as_text(self):
        self.add([(1, "alice"), (2, "bob")])
        self.assertEqual(search(self.conn, "x' OR '1'='1", 10), [])
        self.assertEqual(search(self.conn, "'; DROP TABLE users; --", 10), [])
        self.assertEqual(self.names(""), ["alice", "bob"])

    def test_limit_is_clamped_to_1_through_100(self):
        self.add([(i, f"user{i:03d}") for i in range(1, 151)])
        self.assertEqual(len(search(self.conn, "user", 0)), 1)
        self.assertEqual(len(search(self.conn, "user", -5)), 1)
        self.assertEqual(len(search(self.conn, "user", 7)), 7)
        self.assertEqual(len(search(self.conn, "user", 500)), 100)

    def test_non_integer_limits_raise_value_error(self):
        for bad in (True, False, "5", 5.0, None):
            with self.subTest(limit=bad):
                with self.assertRaises(ValueError):
                    search(self.conn, "a", bad)

    def test_non_string_prefix_raises_type_error(self):
        with self.assertRaises(TypeError):
            search(self.conn, None, 10)


