import os
import sqlite3
import sys
import unittest

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))

from solution import search  # noqa: E402


NAMES = [
    "alice",
    "Alice",
    "al_ice",
    "a%b",
    "axb",
    "a\\b",
    "a\\%",
    "ab",
    "bob",
    "al",
    "zed",
]


class SearchTests(unittest.TestCase):
    def setUp(self):
        self.conn = sqlite3.connect(":memory:")
        self.conn.execute("CREATE TABLE users (id INTEGER, name TEXT)")
        self.conn.executemany(
            "INSERT INTO users (id, name) VALUES (?, ?)",
            [(i, n) for i, n in enumerate(NAMES, start=1)],
        )

    def tearDown(self):
        self.conn.close()

    def names(self, prefix, limit=100):
        return [name for _, name in search(self.conn, prefix, limit)]

    def test_plain_prefix_matches(self):
        self.assertEqual(self.names("al"), ["Alice", "al", "al_ice", "alice"])

    def test_percent_is_literal(self):
        self.assertEqual(self.names("a%"), ["a%b", "a\\%", "a\\b"])

    def test_percent_does_not_match_everything(self):
        self.assertNotIn("bob", self.names("%"))
        self.assertEqual(self.names("%"), ["a%b"])

    def test_underscore_is_literal(self):
        self.assertEqual(self.names("al_"), ["al_ice"])

    def test_underscore_does_not_match_any_char(self):
        self.assertNotIn("alice", self.names("al_"))
        self.assertNotIn("axb", self.names("a_b"))

    def test_backslash_is_literal(self):
        self.assertEqual(self.names("a\\"), ["a\\%", "a\\b"])

    def test_backslash_percent_sequence(self):
        self.assertEqual(self.names("a\\%"), ["a\\%"])

    def test_empty_prefix_matches_all_up_to_limit(self):
        self.assertEqual(len(self.names("")), len(NAMES))

    def test_quote_in_prefix_is_safe(self):
        self.conn.execute("INSERT INTO users (id, name) VALUES (99, 'x''y')")
        self.assertEqual(self.names("x'"), ["x'y"])

    def test_injection_attempt_returns_nothing(self):
        self.assertEqual(self.names("' OR '1'='1"), [])
        self.assertEqual(len(self.conn.execute("SELECT * FROM users").fetchall()), len(NAMES))

    def test_ordering_is_by_name_then_id(self):
        self.conn.execute("INSERT INTO users (id, name) VALUES (0, 'bob')")
        rows = search(self.conn, "bo", 100)
        self.assertEqual(rows, [(0, "bob"), (3, "bob")] if False else [(0, "bob"), (3, "bob")])

    def test_limit_applies(self):
        self.assertEqual(len(self.names("", 3)), 3)

    def test_limit_below_one_is_clamped_to_one(self):
        self.assertEqual(len(self.names("", 0)), 1)
        self.assertEqual(len(self.names("", -5)), 1)

    def test_limit_above_hundred_is_clamped(self):
        for i in range(200):
            self.conn.execute("INSERT INTO users (id, name) VALUES (?, ?)", (1000 + i, f"bulk{i:03d}"))
