_START, _UNQUOTED, _QUOTED, _AFTER_QUOTE = range(4)
_ASCII_DIGITS = frozenset("0123456789")
_MAX_AGE = 130


def read_people(text):
    records = _parse_records(text)
    if not records or records[0] != ["name", "age"]:
        raise ValueError("expected header name,age")
    people = []
    for row, record in enumerate(records[1:], start=2):
        if len(record) != 2:
            raise ValueError(f"row {row}: expected 2 fields, found {len(record)}")
        name, age = record
        people.append({"name": name, "age": _parse_age(age, row)})
    return people


def _parse_age(text, row):
    if not text or not _ASCII_DIGITS.issuperset(text):
        raise ValueError(f"row {row}: invalid age {text!r}")
    age = int(text)
    if age > _MAX_AGE:
        raise ValueError(f"row {row}: age {age} outside 0..{_MAX_AGE}")
    return age


def _parse_records(text):
    records = []
    record = []
    field = []
    state = _START
    i = 0
    while i < len(text):
        ch = text[i]
        i += 1
        if state == _QUOTED:
            if ch == '"':
                state = _AFTER_QUOTE
            else:
                field.append(ch)
            continue
        if ch == "\r" and text.startswith("\n", i):
            i += 1
        if ch in "\r\n":
            if state == _START and not record:
                records.append([])
            else:
                record.append("".join(field))
                records.append(record)
                record = []
                field = []
            state = _START
        elif ch == ",":
            record.append("".join(field))
            field = []
            state = _START
        elif state == _START:
            if ch == '"':
                state = _QUOTED
            else:
                field.append(ch)
                state = _UNQUOTED
        elif state == _UNQUOTED:
            if ch == '"':
                raise ValueError(f"row {len(records) + 1}: quote inside unquoted field")
            field.append(ch)
        else:
            if ch != '"':
                raise ValueError(f"row {len(records) + 1}: text after closing quote")
            field.append(ch)
            state = _QUOTED
    if state == _QUOTED:
        raise ValueError(f"row {len(records) + 1}: unterminated quoted field")
    if state != _START or record:
        record.append("".join(field))
        records.append(record)
    return records

