class ReadPeopleValidTests(unittest.TestCase):
    def test_basic_rows_preserve_order(self):
        text = "name,age\nAlice,30\nBob,41\nCarol,7\n"
        self.assertEqual(
            read_people(text),
            [
                {"name": "Alice", "age": 30},
                {"name": "Bob", "age": 41},
                {"name": "Carol", "age": 7},
            ],
        )

    def test_header_only_returns_empty_list(self):
        self.assertEqual(read_people("name,age\n"), [])

    def test_header_without_trailing_newline(self):
        self.assertEqual(read_people("name,age"), [])

    def test_missing_final_newline(self):
        self.assertEqual(read_people("name,age\nAlice,30"), [{"name": "Alice", "age": 30}])

    def test_crlf_line_endings(self):
        self.assertEqual(
            read_people("name,age\r\nAlice,30\r\nBob,41\r\n"),
            [{"name": "Alice", "age": 30}, {"name": "Bob", "age": 41}],
        )

    def test_quoted_comma_in_name(self):
        self.assertEqual(
            read_people('name,age\n"Smith, Jane",42\n'),
            [{"name": "Smith, Jane", "age": 42}],
        )

    def test_embedded_newline_in_name(self):
        self.assertEqual(
            read_people('name,age\n"Line one\nLine two",5\nBob,6\n'),
            [{"name": "Line one\nLine two", "age": 5}, {"name": "Bob", "age": 6}],
        )

    def test_embedded_crlf_in_quoted_name_is_preserved(self):
        self.assertEqual(
            read_people('name,age\r\n"a\r\nb",5\r\n'),
            [{"name": "a\r\nb", "age": 5}],
        )

    def test_doubled_quotes_unescape(self):
        self.assertEqual(
            read_people('name,age\n"Say ""hi""",7\n'),
            [{"name": 'Say "hi"', "age": 7}],
        )

    def test_empty_quoted_name_is_allowed(self):
        self.assertEqual(read_people('name,age\n"",1\n'), [{"name": "", "age": 1}])

    def test_age_boundaries(self):
        self.assertEqual(
            read_people("name,age\nA,0\nB,130\n"),
            [{"name": "A", "age": 0}, {"name": "B", "age": 130}],
        )

    def test_leading_zeros_are_ascii_digits(self):
        self.assertEqual(read_people("name,age\nA,007\n"), [{"name": "A", "age": 7}])


class ReadPeopleInvalidTests(unittest.TestCase):
    def assertInvalid(self, text):
        with self.assertRaises(ValueError):
            read_people(text)

    def test_empty_input_has_no_header(self):
        self.assertInvalid("")

    def test_wrong_header_order(self):
        self.assertInvalid("age,name\nAlice,30\n")

    def test_wrong_header_case(self):
        self.assertInvalid("Name,Age\nAlice,30\n")

    def test_header_with_extra_column(self):
        self.assertInvalid("name,age,city\nAlice,30,Paris\n")

    def test_header_missing_column(self):
        self.assertInvalid("name\nAlice\n")

    def test_header_with_space_is_different(self):
        self.assertInvalid("name, age\nAlice,30\n")

    def test_row_missing_column(self):
        self.assertInvalid("name,age\nAlice\n")

    def test_row_extra_column(self):
        self.assertInvalid("name,age\nAlice,30,extra\n")

    def test_blank_line_is_a_row_with_missing_columns(self):
        self.assertInvalid("name,age\nAlice,30\n\nBob,41\n")

    def test_invalid_row_after_valid_rows_fails_whole_input(self):
        self.assertInvalid("name,age\nAlice,30\nBob\n")

    def test_unterminated_quote(self):
        self.assertInvalid('name,age\n"Alice,30\n')

    def test_text_after_closing_quote(self):
        self.assertInvalid('name,age\n"Al"ice,30\n')

    def test_space_between_closing_quote_and_delimiter(self):
        self.assertInvalid('name,age\n"Alice" ,30\n')

    def test_quoted_field_in_header_must_still_match(self):
        self.assertInvalid('"name",age,\n')

    def test_negative_age(self):
        self.assertInvalid("name,age\nA,-1\n")

    def test_plus_sign_age(self):
        self.assertInvalid("name,age\nA,+5\n")

    def test_decimal_age(self):
        self.assertInvalid("name,age\nA,3.5\n")

    def test_non_numeric_age(self):
        self.assertInvalid("name,age\nA,abc\n")

    def test_empty_age(self):
        self.assertInvalid("name,age\nA,\n")

    def test_whitespace_around_age(self):
        self.assertInvalid("name,age\nA, 30\n")
        self.assertInvalid("name,age\nA,30 \n")

    def test_non_ascii_digits_rejected(self):
        self.assertInvalid("name,age\nA,３０\n")  # fullwidth "30"
        self.assertInvalid("name,age\nA,٣٠\n")  # Arabic-Indic "30"

    def test_age_above_maximum(self):
        self.assertInvalid("name,age\nA,131\n")

    def test_very_large_age(self):
        self.assertInvalid("name,age\nA," + "9" * 5000 + "\n")


if __name__ == "__main__":
    unittest.main()

async function collectPages(fetchPage) {
  const items = [];
  const seenCursors = new Set();
  let cursor = null;

  for (;;) {
    if (cursor !== null) {
      if (seenCursors.has(cursor)) {
        throw new Error(`collectPages: cursor requested twice: ${JSON.stringify(cursor)}`);
      }
      seenCursors.add(cursor);
    }

    const page = await fetchPage(cursor);
    for (const item of page.items) {
      items.push(item);
    }

    if (page.next === null) {
      return items;
    }
    cursor = page.next;
  }
}

module.exports = { collectPages };

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { collectPages } = require('../src/solution.cjs');

function scripted(pages) {
  const calls = [];
  const fetchPage = async (cursor) => {
    calls.push(cursor);
    const page = pages[calls.length - 1];
    if (page === undefined) {
      throw new Error(`unexpected fetch #${calls.length} with cursor ${JSON.stringify(cursor)}`);
    }
    return page;
  };
  return { fetchPage, calls };
}

test('starts with a null cursor and concatenates pages in order, keeping duplicates', async () => {
  const { fetchPage, calls } = scripted([
    { items: [1, 2], next: 'p2' },
    { items: [2, 3], next: 'p3' },
    { items: [], next: null },
  ]);

  assert.deepEqual(await collectPages(fetchPage), [1, 2, 2, 3]);
  assert.deepEqual(calls, [null, 'p2', 'p3']);
});

test('returns an empty array when the first page has no items and next is null', async () => {
  const { fetchPage } = scripted([{ items: [], next: null }]);
  assert.deepEqual(await collectPages(fetchPage), []);
});

test('continues past an empty intermediate page', async () => {
  const { fetchPage, calls } = scripted([
    { items: ['a'], next: 'c1' },
    { items: [], next: 'c2' },
    { items: ['b'], next: null },
  ]);

  assert.deepEqual(await collectPages(fetchPage), ['a', 'b']);
  assert.deepEqual(calls, [null, 'c1', 'c2']);
});

test('treats an empty-string cursor as a real cursor, not as end of data', async () => {
  const { fetchPage, calls } = scripted([
    { items: ['x'], next: '' },
    { items: ['y'], next: null },
  ]);

  assert.deepEqual(await collectPages(fetchPage), ['x', 'y']);
  assert.deepEqual(calls, [null, '']);
});

test('throws when a non-null cursor would be requested twice', async () => {
  const { fetchPage, calls } = scripted([
    { items: [1], next: 'a' },
    { items: [2], next: 'b' },
    { items: [3], next: 'a' },
  ]);

  await assert.rejects(collectPages(fetchPage), /cursor requested twice/);
  assert.deepEqual(calls, [null, 'a', 'b']);
});

test('throws when the empty-string cursor is repeated', async () => {
  const { fetchPage, calls } = scripted([
    { items: [], next: '' },
    { items: [], next: '' },
  ]);

  await assert.rejects(collectPages(fetchPage), /cursor requested twice/);
  assert.deepEqual(calls, [null, '']);
});

test('propagates a rejected fetch', async () => {
  const failure = new Error('network down');
  const fetchPage = async (cursor) => {
    if (cursor === null) return { items: [1], next: 'p2' };
    throw failure;
  };

  await assert.rejects(collectPages(fetchPage), failure);
});

test('propagates a synchronous throw from fetchPage', async () => {
  const failure = new Error('boom');
  const fetchPage = () => {
    throw failure;
  };

  await assert.rejects(collectPages(fetchPage), failure);
});

