const { test } = require("node:test");
const assert = require("node:assert/strict");
const { collectPages } = require("../src/solution.cjs");

function pagesByCursor(pages) {
  return async (cursor) => {
    const key = cursor === null ? "start" : cursor;
    if (!Object.prototype.hasOwnProperty.call(pages, key)) {
      throw new Error(`unexpected cursor: ${JSON.stringify(cursor)}`);
    }
    return pages[key];
  };
}

test("appends items from every page in order, keeping duplicates", async () => {
  const fetchPage = pagesByCursor({
    start: { items: [1, 2], next: "a" },
    a: { items: [2, 3], next: "b" },
    b: { items: [], next: null },
  });

  assert.deepEqual(await collectPages(fetchPage), [1, 2, 2, 3]);
});

test("first request uses a null cursor and each next cursor is passed on", async () => {
  const requested = [];
  const fetchPage = async (cursor) => {
    requested.push(cursor);
    return cursor === null
      ? { items: ["x"], next: "c1" }
      : { items: ["y"], next: null };
  };

  assert.deepEqual(await collectPages(fetchPage), ["x", "y"]);
  assert.deepEqual(requested, [null, "c1"]);
});

test("an empty intermediate page does not stop collection", async () => {
  const fetchPage = pagesByCursor({
    start: { items: ["a"], next: "p1" },
    p1: { items: [], next: "p2" },
    p2: { items: ["b"], next: null },
  });

  assert.deepEqual(await collectPages(fetchPage), ["a", "b"]);
});

test("empty-string cursor is a valid cursor and does not stop collection", async () => {
  const fetchPage = pagesByCursor({
    start: { items: ["a"], next: "" },
    "": { items: ["b"], next: null },
  });

  assert.deepEqual(await collectPages(fetchPage), ["a", "b"]);
});

test("throws when a non-null cursor is requested twice", async () => {
  const fetchPage = pagesByCursor({
    start: { items: ["a"], next: "x" },
    x: { items: ["b"], next: "y" },
    y: { items: ["c"], next: "x" },
  });

  await assert.rejects(collectPages(fetchPage), /cursor requested twice/);
});

test("throws when the empty-string cursor is requested twice", async () => {
  const fetchPage = pagesByCursor({
    start: { items: ["a"], next: "" },
    "": { items: ["b"], next: "" },
  });

  await assert.rejects(collectPages(fetchPage), /cursor requested twice/);
