test("propagates a rejected fetch", async () => {
  const boom = new Error("network down");
  const fetchPage = pagesByCursor({
    start: { items: ["a"], next: "p1" },
  });
  const failing = async (cursor) => {
    if (cursor === "p1") throw boom;
    return fetchPage(cursor);
  };

  await assert.rejects(collectPages(failing), (err) => err === boom);
});

async function collectPages(fetchPage) {
  const items = [];
  const requested = new Set();
  let cursor = null;

  while (true) {
    const page = await fetchPage(cursor);
    for (const item of page.items) {
      items.push(item);
    }

    if (page.next === null) {
      return items;
    }

    if (requested.has(page.next)) {
      throw new Error(`collectPages: cursor requested twice: ${JSON.stringify(page.next)}`);
    }
    requested.add(page.next);
    cursor = page.next;
  }
}

module.exports = { collectPages };

