function scripted(pages) {
  const calls = [];
  const fetchPage = async (cursor) => {
    calls.push(cursor);
    const page = pages.get(cursor);
    if (!page) throw new Error(`unexpected cursor: ${String(cursor)}`);
    return page;
  };
  return { fetchPage, calls };
}

