async function collectPages(fetchPage) {
  const items = [];
  const requested = new Set();
  let cursor = null;

  for (;;) {
    if (cursor !== null) {
      if (requested.has(cursor)) {
        throw new Error(`collectPages: cursor requested twice: ${JSON.stringify(cursor)}`);
      }
      requested.add(cursor);
    }

    const page = await fetchPage(cursor);
    for (const item of page.items) {
      items.push(item);
    }

    if (page.next === null) {
      return items;
    }
    cursor = page.next;
  }
}

module.exports = { collectPages };

const { test } = require("node:test");
const assert = require("node:assert/strict");
const { collectPages } = require("../src/solution.cjs");

function fakePages(pages) {
  const calls = [];
  const fetchPage = async (cursor) => {
    calls.push(cursor);
    if (!Object.prototype.hasOwnProperty.call(pages, String(cursor))) {
      throw new Error(`unexpected cursor ${JSON.stringify(cursor)}`);
    }
    return pages[String(cursor)];
  };
  return { fetchPage, calls };
}

test("collects items from all pages in order, keeping duplicates", async () => {
  const { fetchPage, calls } = fakePages({
    null: { items: [1, 2], next: "a" },
    a: { items: [2, 3], next: "b" },
    b: { items: [], next: null },
  });

  assert.deepEqual(await collectPages(fetchPage), [1, 2, 2, 3]);
  assert.deepEqual(calls, [null, "a", "b"]);
});

test("returns empty array when the only page is empty and next is null", async () => {
  const { fetchPage } = fakePages({ null: { items: [], next: null } });
  assert.deepEqual(await collectPages(fetchPage), []);
});

test("continues past an empty intermediate page", async () => {
  const { fetchPage, calls } = fakePages({
    null: { items: [1], next: "a" },
    a: { items: [], next: "b" },
    b: { items: [2], next: null },
  });

  assert.deepEqual(await collectPages(fetchPage), [1, 2]);
  assert.deepEqual(calls, [null, "a", "b"]);
});

test("treats empty-string cursor as a real cursor, not as end of pages", async () => {
  const { fetchPage, calls } = fakePages({
    null: { items: [1], next: "" },
    "": { items: [2], next: null },
  });

  assert.deepEqual(await collectPages(fetchPage), [1, 2]);
  assert.deepEqual(calls, [null, ""]);
});

test("throws when a non-null cursor would be requested twice", async () => {
  const { fetchPage, calls } = fakePages({
    null: { items: [1], next: "a" },
    a: { items: [2], next: "b" },
    b: { items: [3], next: "a" },
  });

  await assert.rejects(collectPages(fetchPage), /cursor requested twice/);
  assert.deepEqual(calls, [null, "a", "b"]);
});

test("throws when the first page points back to itself via empty-string cursor", async () => {
  const { fetchPage, calls } = fakePages({
    null: { items: [], next: "" },
    "": { items: [1], next: "" },
  });

  await assert.rejects(collectPages(fetchPage), /cursor requested twice/);
  assert.deepEqual(calls, [null, ""]);
});

