function fakeFetcher(pages) {
  const calls = [];
  const fetchPage = async (cursor) => {
    calls.push(cursor);
    const key = cursor === null ? 'START' : cursor;
    if (!(key in pages)) throw new Error(`unexpected cursor: ${String(cursor)}`);
    return pages[key];
  };
  return { fetchPage, calls };
}

test('collects items from all pages in order, starting with a null cursor', async () => {
  const { fetchPage, calls } = fakeFetcher({
    START: { items: [1, 2], next: 'a' },
    a: { items: [3], next: 'b' },
    b: { items: [4, 5], next: null },
  });

  assert.deepEqual(await collectPages(fetchPage), [1, 2, 3, 4, 5]);
  assert.deepEqual(calls, [null, 'a', 'b']);
});

test('returns an empty array when the only page is empty and ends the stream', async () => {
  const { fetchPage } = fakeFetcher({ START: { items: [], next: null } });
  assert.deepEqual(await collectPages(fetchPage), []);
});

