  const { fetchPage, calls } = fakeFetcher({
    START: { items: ['x'], next: 'p2' },
    p2: { items: [], next: 'p3' },
    p3: { items: ['y'], next: null },
  });

  assert.deepEqual(await collectPages(fetchPage), ['x', 'y']);
  assert.deepEqual(calls, [null, 'p2', 'p3']);
});

test('treats an empty-string cursor as a real cursor, not as end of stream', async () => {
  const { fetchPage, calls } = fakeFetcher({
    START: { items: [1], next: '' },
    '': { items: [2], next: null },
  });

  assert.deepEqual(await collectPages(fetchPage), [1, 2]);
  assert.deepEqual(calls, [null, '']);
});

