'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function assertJsonLike(value) {
  if (typeof value === 'function') {
    throw new TypeError('mergeConfig: functions are not supported');
  }
  if (value === null || typeof value !== 'object') {
    return;
  }
  if (!Array.isArray(value) && !isPlainObject(value)) {
    throw new TypeError('mergeConfig: only plain objects, arrays and scalars are supported');
  }
  for (const key of Reflect.ownKeys(value)) {
    if (typeof key === 'string' && UNSAFE_KEYS.has(key)) {
      throw new Error(`mergeConfig: unsafe key "${key}"`);
    }
  }
  for (const key of Object.keys(value)) {
    assertJsonLike(value[key]);
  }
}

function deepCopy(value) {
  if (value === null || typeof value !== 'object') {
    return value;
  }
  if (Array.isArray(value)) {
    return value.map((item) => deepCopy(item));
  }
  const copy = {};
  for (const key of Object.keys(value)) {
    copy[key] = deepCopy(value[key]);
  }
  return copy;
}

function mergeObjects(base, override) {
  const result = {};
  for (const key of Object.keys(base)) {
    result[key] = deepCopy(base[key]);
  }
  for (const key of Object.keys(override)) {
    const overrideValue = override[key];
    const mergeNested =
      Object.prototype.hasOwnProperty.call(base, key) &&
      isPlainObject(base[key]) &&
      isPlainObject(overrideValue);
    result[key] = mergeNested
      ? mergeObjects(base[key], overrideValue)
      : deepCopy(overrideValue);
  }
  return result;
}

function assertConfigObject(value, name) {
  if (!isPlainObject(value)) {
    throw new TypeError(`mergeConfig: ${name} must be a plain object`);
  }
  assertJsonLike(value);
}

function mergeConfig(base, override) {
  assertConfigObject(base, 'base');
  assertConfigObject(override, 'override');
  return mergeObjects(base, override);
}

module.exports = { mergeConfig };

'use strict';

const { describe, test } = require('node:test');
const assert = require('node:assert/strict');
const { mergeConfig } = require('../src/solution.cjs');

function withOwnKey(key, value, extra = {}) {
  const obj = { ...extra };
  Object.defineProperty(obj, key, {
    value,
    enumerable: true,
    writable: true,
    configurable: true,
  });
  return obj;
}

function collectContainers(value, set = new Set()) {
  if (value !== null && typeof value === 'object') {
    set.add(value);
    for (const key of Object.keys(value)) {
      collectContainers(value[key], set);
    }
  }
  return set;
}

describe('nested merges', () => {
  test('merges plain objects recursively and keeps untouched keys', () => {
    const base = { a: { b: 1, c: { d: 2 } }, e: 1 };
    const override = { a: { c: { f: 3 } }, g: 4 };
    assert.deepEqual(mergeConfig(base, override), {
      a: { b: 1, c: { d: 2, f: 3 } },
      e: 1,
      g: 4,
    });
  });

  test('override adds keys absent from base at nested levels', () => {
    const result = mergeConfig({ a: { x: 1 } }, { a: { y: { z: 2 } } });
    assert.deepEqual(result, { a: { x: 1, y: { z: 2 } } });
  });

  test('empty override returns an equal copy of base', () => {
    const base = { a: { b: [1, 2] } };
    assert.deepEqual(mergeConfig(base, {}), base);
  });
});

describe('replacement', () => {
  test('arrays are replaced, not concatenated or merged by index', () => {
    const base = { list: [1, { x: 1 }, 3] };
    const override = { list: [{ y: 2 }] };
    assert.deepEqual(mergeConfig(base, override), { list: [{ y: 2 }] });
  });

  test('array replaces a base object at the same key', () => {
    assert.deepEqual(mergeConfig({ a: { x: 1 } }, { a: [1] }), { a: [1] });
  });

  test('object replaces a base array at the same key', () => {
    assert.deepEqual(mergeConfig({ a: [1] }, { a: { x: 1 } }), { a: { x: 1 } });
  });

  test('scalars replace objects and objects replace scalars', () => {
    const result = mergeConfig({ a: { x: 1 }, b: 1 }, { a: 2, b: { y: 2 } });
    assert.deepEqual(result, { a: 2, b: { y: 2 } });
  });

  test('null and false replace base values', () => {
    const result = mergeConfig({ a: { x: 1 }, b: true }, { a: null, b: false });
    assert.deepEqual(result, { a: null, b: false });
  });

  test('arrays nested under merged objects are replaced', () => {
    const result = mergeConfig(
      { server: { hosts: ['a', 'b'], port: 80 } },
      { server: { hosts: ['c'] } },
    );
    assert.deepEqual(result, { server: { hosts: ['c'], port: 80 } });
  });
});

describe('inputs and aliasing', () => {
  test('does not mutate base or override', () => {
    const base = { a: { b: 1, list: [{ c: 1 }] }, keep: { deep: [1, 2] } };
    const override = { a: { list: [{ d: 2 }], n: { m: 3 } } };
    const baseSnapshot = JSON.parse(JSON.stringify(base));
    const overrideSnapshot = JSON.parse(JSON.stringify(override));

    mergeConfig(base, override);

    assert.deepEqual(base, baseSnapshot);
    assert.deepEqual(override, overrideSnapshot);
  });

  test('result shares no nested objects or arrays with base or override', () => {
    const base = { a: { b: { c: 1 } }, list: [{ x: 1 }], kept: { deep: [1, [2]] } };
    const override = { a: { n: { m: 1 } }, list: [{ y: 2 }] };
    const result = mergeConfig(base, override);

    const inputContainers = new Set([
      ...collectContainers(base),
      ...collectContainers(override),
    ]);
    for (const container of collectContainers(result)) {
      assert.equal(inputContainers.has(container), false);
    }
  });

  test('mutating the result does not affect base or override', () => {
    const base = { a: { b: 1 }, list: [{ c: 1 }] };
    const override = { a: { d: { e: 2 } }, list: [{ f: 3 }] };
    const result = mergeConfig(base, override);

    result.a.b = 99;
    result.a.d.e = 99;
    result.list[0].f = 99;
    result.kept = 1;

    assert.deepEqual(base, { a: { b: 1 }, list: [{ c: 1 }] });
    assert.deepEqual(override, { a: { d: { e: 2 } }, list: [{ f: 3 }] });
  });

  test('mutating base or override after merge does not affect result', () => {
    const base = { a: { b: [1] } };
    const override = { c: { d: [2] } };
    const result = mergeConfig(base, override);

    base.a.b.push(9);
    override.c.d.push(9);

    assert.deepEqual(result, { a: { b: [1] }, c: { d: [2] } });
  });

  test('same nested object reused in base and override is not shared in result', () => {
    const shared = { x: [1] };
    const result = mergeConfig({ a: shared }, { b: shared });
    assert.notEqual(result.a, shared);
    assert.notEqual(result.b, shared);
    assert.notEqual(result.a, result.b);
    assert.deepEqual(result, { a: { x: [1] }, b: { x: [1] } });
  });

  test('result has ordinary object prototype', () => {
    const result = mergeConfig({ a: { b: 1 } }, { a: { c: 2 } });
    assert.equal(Object.getPrototypeOf(result), Object.prototype);
    assert.equal(Object.getPrototypeOf(result.a), Object.prototype);
  });
});

describe('unsafe keys', () => {
  for (const key of ['__proto__', 'constructor', 'prototype']) {
    const message = new RegExp(`unsafe key "${key}"`);

    test(`rejects own "${key}" at top level of base`, () => {
      assert.throws(() => mergeConfig(withOwnKey(key, 1), {}), message);
    });

    test(`rejects own "${key}" at top level of override`, () => {
      assert.throws(() => mergeConfig({}, withOwnKey(key, 1)), message);
    });

    test(`rejects own "${key}" nested in base`, () => {
      const base = { a: { b: withOwnKey(key, 1) } };
      assert.throws(() => mergeConfig(base, {}), message);
    });

    test(`rejects own "${key}" nested in override`, () => {
      const override = { a: { b: withOwnKey(key, 1) } };
      assert.throws(() => mergeConfig({ a: { b: 1 } }, override), message);
    });

    test(`rejects own "${key}" inside an array in base`, () => {
      const base = { list: [{ ok: 1 }, withOwnKey(key, 1)] };
      assert.throws(() => mergeConfig(base, {}), message);
    });

    test(`rejects own "${key}" inside an array in override`, () => {
      const override = { list: [[withOwnKey(key, 1)]] };
      assert.throws(() => mergeConfig({}, override), message);
    });

    test(`rejects own "${key}" in base value replaced by override`, () => {
      const base = { a: withOwnKey(key, 1) };
      assert.throws(() => mergeConfig(base, { a: 1 }), message);
    });

    test(`rejects own "${key}" in override value replacing a base value`, () => {
      const override = { a: [withOwnKey(key, 1)] };
