'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function isPlainArray(value) {
  return Array.isArray(value) && Object.getPrototypeOf(value) === Array.prototype;
}

function assertJsonLike(value) {
  if (value === null) {
    return;
  }
  const type = typeof value;
  if (type === 'string' || type === 'number' || type === 'boolean') {
    return;
  }
  if (isPlainArray(value)) {
    for (const item of value) {
      assertJsonLike(item);
    }
    return;
  }
  if (isPlainObject(value)) {
    for (const key of Object.getOwnPropertyNames(value)) {
      if (UNSAFE_KEYS.has(key)) {
        throw new TypeError(`Unsafe key "${key}" is not allowed in config`);
      }
      assertJsonLike(value[key]);
    }
    return;
  }
  throw new TypeError(`Unsupported config value of type ${type}`);
}

function cloneValue(value) {
  if (isPlainArray(value)) {
    return value.map(cloneValue);
  }
  if (isPlainObject(value)) {
    const copy = {};
    for (const key of Object.keys(value)) {
      copy[key] = cloneValue(value[key]);
    }
    return copy;
  }
  return value;
}

function mergeObjects(base, override) {
  const result = {};
  for (const key of Object.keys(base)) {
    result[key] = cloneValue(base[key]);
  }
  for (const key of Object.keys(override)) {
    const overrideValue = override[key];
    if (
      isPlainObject(overrideValue) &&
      Object.hasOwn(base, key) &&
      isPlainObject(base[key])
    ) {
      result[key] = mergeObjects(base[key], overrideValue);
    } else {
      result[key] = cloneValue(overrideValue);
    }
  }
  return result;
}

function mergeConfig(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) {
    throw new TypeError('mergeConfig expects plain object arguments');
  }
  assertJsonLike(base);
  assertJsonLike(override);
  return mergeObjects(base, override);
}

module.exports = { mergeConfig };

