'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function hasOwn(object, key) {
  return Object.prototype.hasOwnProperty.call(object, key);
}

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function assertJsonLike(value, path) {
  if (value === null || typeof value === 'string' || typeof value === 'boolean') {
    return;
  }
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) {
      throw new TypeError(`Non-finite number at ${path}`);
    }
    return;
  }
  if (Array.isArray(value)) {
    for (let i = 0; i < value.length; i++) {
      assertJsonLike(value[i], `${path}[${i}]`);
    }
    return;
  }
  if (isPlainObject(value)) {
    for (const key of Object.getOwnPropertyNames(value)) {
      if (UNSAFE_KEYS.has(key)) {
        throw new TypeError(`Unsafe key "${key}" at ${path}`);
      }
      assertJsonLike(value[key], `${path}.${key}`);
    }
    return;
  }
  throw new TypeError(`Unsupported value at ${path}`);
}

function deepCopy(value) {
  if (Array.isArray(value)) {
    const copy = new Array(value.length);
    for (let i = 0; i < value.length; i++) {
      copy[i] = deepCopy(value[i]);
    }
    return copy;
  }
  if (isPlainObject(value)) {
    const copy = {};
    for (const key of Object.keys(value)) {
      copy[key] = deepCopy(value[key]);
    }
    return copy;
  }
  return value;
}

function mergeObjects(base, override) {
  const result = {};
  for (const key of Object.keys(base)) {
    result[key] = deepCopy(base[key]);
  }
  for (const key of Object.keys(override)) {
    const overrideValue = override[key];
    if (isPlainObject(overrideValue) && hasOwn(base, key) && isPlainObject(base[key])) {
      result[key] = mergeObjects(base[key], overrideValue);
    } else {
      result[key] = deepCopy(overrideValue);
    }
  }
  return result;
}

function mergeConfig(base, override) {
  if (!isPlainObject(base)) {
    throw new TypeError('base must be a plain object');
  }
  if (!isPlainObject(override)) {
    throw new TypeError('override must be a plain object');
  }
  assertJsonLike(base, 'base');
  assertJsonLike(override, 'override');
  return mergeObjects(base, override);
}

