    if (a.remainder !== b.remainder) return a.remainder > b.remainder ? -1 : 1;
    return a.index - b.index;
  });
  for (let k = 0; k < leftover; k++) {
    byRemainder[k].quota += 1n;
  }

  return shares.map((share) => Number(share.quota));
