const MAX_SAFE = Number.MAX_SAFE_INTEGER;

function splitCents(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw new RangeError('total must be a nonnegative safe integer');
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('weights must be a nonempty array');
  }

  let weightSum = 0;
  for (const weight of weights) {
    if (!Number.isSafeInteger(weight) || weight <= 0) {
      throw new RangeError('weights must contain positive safe integers');
    }
    weightSum += weight;
    if (weightSum > MAX_SAFE) {
      throw new RangeError('sum of weights exceeds the safe integer range');
    }
    if (total * weight > MAX_SAFE) {
      throw new RangeError('total * weight exceeds the safe integer range');
    }
  }

  const shares = new Array(weights.length);
  const remainders = new Array(weights.length);
  let allocated = 0;
  for (let i = 0; i < weights.length; i++) {
    const product = total * weights[i];
    // Math.floor(product / weightSum) can round up near an integer; take the exact remainder first.
    const remainder = product % weightSum;
    shares[i] = (product - remainder) / weightSum;
    remainders[i] = remainder;
    allocated += shares[i];
  }

  const leftover = total - allocated;
  const order = weights
    .map((_, i) => i)
    .sort((a, b) => remainders[b] - remainders[a] || a - b);
  for (let k = 0; k < leftover; k++) {
    shares[order[k]] += 1;
  }

  return shares;
}

module.exports = { splitCents };

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { splitCents } = require('../src/solution.cjs');

const sum = (values) => values.reduce((acc, v) => acc + v, 0);

test('even split distributes remainder to earliest tied indices', () => {
  assert.deepEqual(splitCents(10, [1, 1, 1]), [4, 3, 3]);
  assert.deepEqual(splitCents(5, [1, 1]), [3, 2]);
  assert.deepEqual(splitCents(2, [1, 1, 1, 1]), [1, 1, 0, 0]);
});

test('ties in fractional remainders are broken by earlier index', () => {
  assert.deepEqual(splitCents(10, [3, 1]), [8, 2]);
  assert.deepEqual(splitCents(7, [1, 1, 1]), [3, 2, 2]);
});

test('leftover goes to largest remainder, not first index', () => {
  assert.deepEqual(splitCents(10, [2, 3, 4]), [2, 3, 5]);
});

test('zero total yields all zeros and still validates weights', () => {
  assert.deepEqual(splitCents(0, [3, 5]), [0, 0]);
  assert.deepEqual(splitCents(0, [1]), [0]);
  assert.throws(() => splitCents(0, []), RangeError);
});

test('uneven quotas are floored and remainders allocated', () => {
  assert.deepEqual(splitCents(100, [1, 2, 3]), [17, 33, 50]);
  assert.deepEqual(splitCents(1, [1, 2, 3]), [0, 0, 1]);
