const MAX_SAFE = Number.MAX_SAFE_INTEGER;

function splitCents(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw new RangeError('total must be a nonnegative safe integer');
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('weights must be a nonempty array');
  }

  let weightSum = 0;
  for (const weight of weights) {
    if (!Number.isSafeInteger(weight) || weight <= 0) {
      throw new RangeError('weights must be positive safe integers');
    }
    if (weight > MAX_SAFE - weightSum) {
      throw new RangeError('sum of weights exceeds the safe integer range');
    }
    if (total * weight > MAX_SAFE) {
      throw new RangeError('total * weight exceeds the safe integer range');
    }
    weightSum += weight;
  }

  // BigInt keeps the quota division and remainder exact.
  const bigTotal = BigInt(total);
  const bigSum = BigInt(weightSum);
  const quotas = weights.map((weight) => {
    const product = bigTotal * BigInt(weight);
    return { floor: product / bigSum, remainder: product % bigSum };
  });

  const result = quotas.map((quota) => Number(quota.floor));
  const leftover = total - result.reduce((acc, value) => acc + value, 0);

  const order = quotas.map((_, index) => index).sort((a, b) => {
    const diff = quotas[b].remainder - quotas[a].remainder;
    if (diff !== 0n) return diff > 0n ? 1 : -1;
    return a - b;
  });

  for (let k = 0; k < leftover; k++) {
    result[order[k]] += 1;
  }

  return result;
}

module.exports = { splitCents };

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { splitCents } = require('../src/solution.cjs');

const sum = (values) => values.reduce((acc, value) => acc + value, 0);

test('ties give leftover cents to earlier indices', () => {
  assert.deepEqual(splitCents(5, [1, 1, 1]), [2, 2, 1]);
  assert.deepEqual(splitCents(1, [1, 1]), [1, 0]);
  assert.deepEqual(splitCents(3, [2, 2]), [2, 1]);
