test('zero total yields all zeros while still validating weights', () => {
  assert.deepEqual(splitCents(0, [1, 2, 3]), [0, 0, 0]);
  assert.deepEqual(splitCents(0, [7]), [0]);
  assert.throws(() => splitCents(0, [0]), RangeError);
});

test('uneven quotas use largest remainders', () => {
  assert.deepEqual(splitCents(10, [1, 2, 3]), [2, 3, 5]);
  assert.deepEqual(splitCents(7, [3, 1]), [5, 2]);
  assert.deepEqual(splitCents(100, [1, 2, 4]), [14, 29, 57]);
});

test('exact division allocates no leftovers', () => {
  assert.deepEqual(splitCents(10, [1, 4]), [2, 8]);
});

test('results sum to total at safe-integer precision', () => {
  const total = 2 ** 52 + 1;
  const result = splitCents(total, [1, 1]);
  assert.deepEqual(result, [2 ** 51 + 1, 2 ** 51]);
  assert.equal(sum(result), total);
});

test('does not mutate weights', () => {
  const weights = [3, 1, 2];
  splitCents(10, weights);
  assert.deepEqual(weights, [3, 1, 2]);
});

test('invalid total throws RangeError', () => {
  for (const total of [-1, 1.5, NaN, Infinity, 2 ** 53, '10']) {
    assert.throws(() => splitCents(total, [1]), RangeError);
  }
