    def test_positive_offset_moves_instant_to_previous_utc_day(self):
        self.assertDay("2025-01-01T00:30:00+02:00", 2024, 12, 31)

    def test_negative_offset_moves_instant_to_next_utc_day(self):
        self.assertDay("2025-01-01T23:30:00-02:00", 2025, 1, 2)

    def test_offset_at_exact_utc_midnight_boundary(self):
        self.assertDay("2025-01-01T02:00:00+02:00", 2025, 1, 1)
        self.assertDay("2025-01-01T00:00:00+00:00", 2025, 1, 1)

    def test_z_suffix_is_utc(self):
        self.assertDay("2025-03-10T23:59:59Z", 2025, 3, 10)

    def test_fractional_seconds_are_ignored(self):
        self.assertDay("2025-06-15T00:00:00.123+01:00", 2025, 6, 14)

    def test_leap_day_is_preserved(self):
        self.assertDay("2024-02-29T12:00:00Z", 2024, 2, 29)

    def test_leap_day_boundary_with_offset(self):
        self.assertDay("2024-02-29T00:30:00+01:00", 2024, 2, 28)
        self.assertDay("2024-02-29T23:30:00-01:00", 2024, 3, 1)

    def test_non_leap_year_february_end(self):
        self.assertDay("2025-02-28T23:30:00-01:00", 2025, 3, 1)

    def test_result_has_midnight_time_fields(self):
        result = utc_day_start("2025-07-04T13:45:10.500-05:00")
        self.assertEqual((result.hour, result.minute, result.second, result.microsecond),
                         (0, 0, 0, 0))
        self.assertEqual(result.utcoffset().total_seconds(), 0)

    def test_result_does_not_depend_on_machine_timezone(self):
        if not hasattr(time, "tzset"):
            self.skipTest("time.tzset not available on this platform")
        original = os.environ.get("TZ")
        try:
            os.environ["TZ"] = "America/New_York"
            time.tzset()
            self.assertDay("2025-01-01T00:30:00+02:00", 2024, 12, 31)
        finally:
            if original is None:
                os.environ.pop("TZ", None)
            else:
                os.environ["TZ"] = original
            time.tzset()

    def test_naive_timestamp_is_rejected(self):
        with self.assertRaises(ValueError):
            utc_day_start("2025-01-01T00:30:00")

    def test_naive_date_only_is_rejected(self):
        with self.assertRaises(ValueError):
            utc_day_start("2025-01-01")

    def test_invalid_strings_are_rejected(self):
        for text in ["", "not-a-date", "2025-13-01T00:00:00Z",
