def utc_day_start(text):
    if not isinstance(text, str):
        raise ValueError("timestamp must be a string")
    value = text[:-1] + "+00:00" if text.endswith("Z") else text
    try:
        instant = datetime.fromisoformat(value)
    except ValueError:
        raise ValueError(f"invalid ISO 8601 timestamp: {text!r}") from None
    if instant.utcoffset() is None:
        raise ValueError("timestamp must include a UTC offset or Z")
    try:
        utc = instant.astimezone(timezone.utc)
    except OverflowError:
        raise ValueError("timestamp is out of range") from None
    return utc.replace(hour=0, minute=0, second=0, microsecond=0)

