sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))

from solution import utc_day_start  # noqa: E402


def utc(*args):
    return datetime(*args, tzinfo=timezone.utc)


class UtcDayStartTests(unittest.TestCase):
    def test_z_suffix_keeps_same_day(self):
        self.assertEqual(utc_day_start("2025-01-01T12:00:00Z"), utc(2025, 1, 1))

    def test_exact_midnight_utc_is_its_own_day_start(self):
        self.assertEqual(utc_day_start("2025-01-01T00:00:00Z"), utc(2025, 1, 1))

    def test_positive_offset_moves_to_previous_utc_day(self):
        result = utc_day_start("2025-01-01T00:30:00+02:00")
        self.assertEqual(result, utc(2024, 12, 31))
        self.assertIs(result.tzinfo, timezone.utc)

    def test_negative_offset_moves_to_next_utc_day(self):
        self.assertEqual(
            utc_day_start("2025-01-01T23:30:00-02:00"), utc(2025, 1, 2)
        )

    def test_offset_at_exact_boundary(self):
        self.assertEqual(
            utc_day_start("2025-01-01T00:00:00+00:00"), utc(2025, 1, 1)
        )
        self.assertEqual(
            utc_day_start("2025-01-01T02:00:00+02:00"), utc(2025, 1, 1)
        )

    def test_fractional_seconds_are_discarded(self):
        self.assertEqual(
            utc_day_start("2025-06-15T23:59:59.999999Z"), utc(2025, 6, 15)
        )

    def test_leap_day_itself(self):
        self.assertEqual(
            utc_day_start("2024-02-29T23:59:59.999999Z"), utc(2024, 2, 29)
        )

    def test_offset_crossing_into_leap_day(self):
        self.assertEqual(
            utc_day_start("2024-03-01T00:30:00+01:00"), utc(2024, 2, 29)
        )

    def test_offset_crossing_out_of_leap_day(self):
        self.assertEqual(
            utc_day_start("2024-02-29T23:30:00-01:00"), utc(2024, 3, 1)
        )

    def test_non_leap_year_february_end(self):
        self.assertEqual(
            utc_day_start("2025-03-01T00:30:00+01:00"), utc(2025, 2, 28)
        )

    def test_result_does_not_depend_on_machine_timezone(self):
        if not hasattr(time, "tzset"):
            self.skipTest("time.tzset not available")
        original = os.environ.get("TZ")
        try:
            for zone in ("America/New_York", "Asia/Kolkata", "Pacific/Kiritimati"):
                os.environ["TZ"] = zone
                time.tzset()
                self.assertEqual(
                    utc_day_start("2025-01-01T00:30:00+02:00"), utc(2024, 12, 31)
                )
        finally:
            if original is None:
                os.environ.pop("TZ", None)
            else:
                os.environ["TZ"] = original
            time.tzset()

    def test_naive_timestamp_is_rejected(self):
        with self.assertRaises(ValueError):
            utc_day_start("2025-01-01T00:30:00")

    def test_date_only_is_rejected(self):
        with self.assertRaises(ValueError):
            utc_day_start("2025-01-01")

    def test_invalid_strings_are_rejected(self):
        for bad in (
            "",
            "Z",
            "not a timestamp",
            "2025-13-01T00:00:00Z",
            "2025-02-30T00:00:00Z",
            "2025-01-01T25:00:00Z",
            "2025-01-01T00:00:00+02:00Z",
        ):
            with self.subTest(text=bad):
                with self.assertRaises(ValueError):
                    utc_day_start(bad)

    def test_non_string_input_is_rejected(self):
        for bad in (None, 20250101, datetime(2025, 1, 1, tzinfo=timezone.utc)):
            with self.subTest(value=bad):
                with self.assertRaises(ValueError):
                    utc_day_start(bad)

    def test_out_of_range_timestamp_is_rejected(self):
        with self.assertRaises(ValueError):
            utc_day_start("0001-01-01T00:00:00+01:00")


if __name__ == "__main__":
    unittest.main()

from datetime import datetime, timezone


def utc_day_start(text):
    if not isinstance(text, str):
        raise ValueError("timestamp must be a string")
    value = text[:-1] + "+00:00" if text.endswith("Z") else text
    try:
        instant = datetime.fromisoformat(value)
    except ValueError as exc:
        raise ValueError(f"invalid ISO 8601 timestamp: {text!r}") from exc
    if instant.tzinfo is None:
        raise ValueError(f"timestamp must include a UTC offset: {text!r}")
    utc = instant.astimezone(timezone.utc)
    return datetime(utc.year, utc.month, utc.day, tzinfo=timezone.utc)

