sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))

from solution import decode_chunks  # noqa: E402


class DecodeChunksTest(unittest.TestCase):
    def test_empty_iterable(self):
        self.assertEqual(decode_chunks([]), "")

    def test_empty_chunks_are_valid(self):
        self.assertEqual(decode_chunks([b"", b"hi", b"", b"!", b""]), "hi!")

    def test_ascii_single_chunk(self):
        self.assertEqual(decode_chunks([b"hello"]), "hello")

    def test_multibyte_character_split_across_chunks(self):
        # "€" is b"\xe2\x82\xac"; split after the first byte.
        self.assertEqual(decode_chunks([b"a\xe2", b"\x82\xac", b"b"]), "a€b")

    def test_four_byte_character_split_one_byte_per_chunk(self):
        # "😀" is b"\xf0\x9f\x98\x80".
        data = "x😀y".encode("utf-8")
        self.assertEqual(decode_chunks([data[i:i + 1] for i in range(len(data))]), "x😀y")

    def test_accepts_generator(self):
        def gen():
            yield "naïve ".encode("utf-8")[:3]
            yield "naïve ".encode("utf-8")[3:]

        self.assertEqual(decode_chunks(gen()), "naïve ")

    def test_incomplete_final_character_raises(self):
        with self.assertRaises(UnicodeDecodeError):
            decode_chunks([b"ab\xe2\x82"])

    def test_incomplete_final_character_across_chunks_raises(self):
        with self.assertRaises(UnicodeDecodeError):
            decode_chunks([b"ab\xe2", b"\x82"])

    def test_invalid_byte_raises(self):
        with self.assertRaises(UnicodeDecodeError):
            decode_chunks([b"ok", b"\xff", b"more"])

    def test_invalid_continuation_across_chunks_raises(self):
        with self.assertRaises(UnicodeDecodeError):
            decode_chunks([b"\xe2", b"A"])

    def test_surrogate_encoding_raises(self):
        with self.assertRaises(UnicodeDecodeError):
            decode_chunks([b"\xed\xa0\x80"])


if __name__ == "__main__":
    unittest.main()

