class DecodeChunksTests(unittest.TestCase):
    def test_single_chunk(self):
        self.assertEqual(decode_chunks([b"hello"]), "hello")

    def test_empty_iterable(self):
        self.assertEqual(decode_chunks([]), "")

    def test_empty_chunks_are_ignored(self):
        self.assertEqual(decode_chunks([b"", b"ab", b"", b"c", b""]), "abc")

    def test_two_byte_character_split_across_chunks(self):
        # "é" is C3 A9
        self.assertEqual(decode_chunks([b"caf\xc3", b"\xa9"]), "café")

    def test_three_byte_character_split_across_chunks(self):
        # "€" is E2 82 AC
        self.assertEqual(decode_chunks([b"\xe2", b"\x82", b"\xac"]), "€")
        self.assertEqual(decode_chunks([b"x\xe2\x82", b"\xacy"]), "x€y")

    def test_four_byte_character_split_across_chunks(self):
        # "😀" is F0 9F 98 80
        emoji = "😀".encode("utf-8")
        self.assertEqual(decode_chunks([emoji[:1], emoji[1:3], emoji[3:]]), "😀")

    def test_every_byte_boundary(self):
        text = "naïve café € 😀 end"
        data = text.encode("utf-8")
        chunks = [data[i:i + 1] for i in range(len(data))]
        self.assertEqual(decode_chunks(chunks), text)

    def test_lazy_iterable(self):
        def gen():
            yield b"\xe2\x82"
            yield b""
            yield b"\xac"

        self.assertEqual(decode_chunks(gen()), "€")

    def test_incomplete_final_character_raises(self):
        with self.assertRaises(UnicodeDecodeError):
            decode_chunks([b"abc\xe2\x82"])

    def test_incomplete_final_character_split_across_chunks_raises(self):
        with self.assertRaises(UnicodeDecodeError):
            decode_chunks([b"abc\xe2", b"\x82"])

    def test_lone_continuation_byte_raises(self):
        with self.assertRaises(UnicodeDecodeError):
            decode_chunks([b"ab\x80cd"])

    def test_invalid_start_byte_raises(self):
        with self.assertRaises(UnicodeDecodeError):
            decode_chunks([b"\xff"])

    def test_encoded_surrogate_raises(self):
        with self.assertRaises(UnicodeDecodeError):
            decode_chunks([b"\xed", b"\xa0\x80"])

    def test_overlong_encoding_raises(self):
        with self.assertRaises(UnicodeDecodeError):
            decode_chunks([b"\xc0\xaf"])


