'use strict';

const VERSION_PATTERN = /^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$/;

function parseVersion(version, name) {
  if (typeof version !== 'string') {
    throw new TypeError(`${name} must be a string`);
  }
  const match = VERSION_PATTERN.exec(version);
  if (match === null) {
    throw new TypeError(`${name} is not a valid MAJOR.MINOR.PATCH version`);
  }
  return match.slice(1).map(BigInt);
}

function compareVersion(a, b) {
  const left = parseVersion(a, 'a');
  const right = parseVersion(b, 'b');
  for (let i = 0; i < 3; i++) {
    if (left[i] !== right[i]) {
      return left[i] < right[i] ? -1 : 1;
    }
  }
  return 0;
}

module.exports = { compareVersion };

'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { compareVersion } = require('../src/solution.cjs');

test('compares components numerically, not lexicographically', () => {
  assert.equal(compareVersion('1.10.0', '1.2.9'), 1);
  assert.equal(compareVersion('1.2.9', '1.10.0'), -1);
});

test('earlier components take precedence over later ones', () => {
  assert.equal(compareVersion('2.0.0', '1.99999.99999'), 1);
  assert.equal(compareVersion('1.2.0', '1.1.99999'), 1);
});

test('returns 0 for equal versions', () => {
  assert.equal(compareVersion('0.0.0', '0.0.0'), 0);
  assert.equal(compareVersion('1.2.3', '1.2.3'), 0);
});

test('handles components beyond Number.MAX_SAFE_INTEGER exactly', () => {
  const maxSafe = String(Number.MAX_SAFE_INTEGER);
  const beyond = '9007199254740993';
  assert.equal(compareVersion(`${beyond}.0.0`, `${maxSafe}.0.0`), 1);
  assert.equal(compareVersion(`${maxSafe}.0.0`, `${beyond}.0.0`), -1);
  assert.equal(compareVersion(`0.${beyond}.0`, `0.${beyond}.0`), 0);
  assert.equal(compareVersion('0.0.9007199254740992', '0.0.9007199254740993'), -1);
  assert.equal(
    compareVersion('0.0.18446744073709551616', '0.0.18446744073709551615'),
    1,
  );
  assert.equal(
    compareVersion('99999999999999999999999.0.0', '100000000000000000000000.0.0'),
    -1,
  );
});

test('accepts zero components and single-digit leading zero', () => {
  assert.equal(compareVersion('0.0.1', '0.1.0'), -1);
  assert.equal(compareVersion('10.0.0', '9.0.0'), 1);
});

test('throws TypeError for non-string input', () => {
  for (const value of [undefined, null, 123, 1.2, {}, ['1.2.3'], Buffer.from('1.2.3')]) {
    assert.throws(() => compareVersion(value, '1.2.3'), TypeError);
    assert.throws(() => compareVersion('1.2.3', value), TypeError);
  }
});

test('throws TypeError for malformed version strings', () => {
  const malformed = [
    '',
    '1',
    '1.2',
    '1.2.3.4',
    '1..3',
    '.1.2',
    '1.2.',
