const COMPONENT = '(0|[1-9][0-9]*)';
const VERSION_PATTERN = new RegExp(`^${COMPONENT}\\.${COMPONENT}\\.${COMPONENT}$`);

function parseVersion(version, name) {
  if (typeof version !== 'string' || !VERSION_PATTERN.test(version)) {
    throw new TypeError(`${name} must be a version string of three dot-separated non-negative integers without leading zeros`);
  }
  return version.split('.').map((part) => BigInt(part));
}

function compareVersion(a, b) {
  const left = parseVersion(a, 'a');
  const right = parseVersion(b, 'b');
  for (let i = 0; i < 3; i++) {
    if (left[i] !== right[i]) {
      return left[i] < right[i] ? -1 : 1;
    }
  }
  return 0;
}

module.exports = { compareVersion };

