class Emitter {
  #listeners = new Map();

  on(event, fn) {
    let list = this.#listeners.get(event);
    if (!list) {
      list = [];
      this.#listeners.set(event, list);
    }

    let entry = list.find((item) => item.fn === fn);
    if (!entry) {
      entry = { fn };
      list.push(entry);
    }

    return () => {
      const index = list.indexOf(entry);
      if (index !== -1) list.splice(index, 1);
    };
  }

  emit(event, value) {
    const list = this.#listeners.get(event);
    if (!list) return;

    const snapshot = list.map((entry) => entry.fn);
    for (const fn of snapshot) {
      fn(value);
    }
  }

  off(event, fn) {
    const list = this.#listeners.get(event);
    if (!list) return;

    const index = list.findIndex((entry) => entry.fn === fn);
    if (index !== -1) list.splice(index, 1);
  }
}

