class Emitter {
  #events = new Map();

  on(event, fn) {
    const registrations = this.#events.get(event) ?? [];
    if (registrations.some((registration) => registration.fn === fn)) {
      return () => {};
    }
    const registration = { fn };
    registrations.push(registration);
    this.#events.set(event, registrations);
    return () => this.#remove(event, registration);
  }

  off(event, fn) {
    const registrations = this.#events.get(event);
    if (!registrations) return;
    const registration = registrations.find((entry) => entry.fn === fn);
    if (registration) this.#remove(event, registration);
  }

  emit(event, value) {
    const registrations = this.#events.get(event);
    if (!registrations) return;
    for (const { fn } of registrations.slice()) {
      fn(value);
    }
  }

  #remove(event, registration) {
    const registrations = this.#events.get(event);
    if (!registrations) return;
    const index = registrations.indexOf(registration);
    if (index === -1) return;
    registrations.splice(index, 1);
    if (registrations.length === 0) this.#events.delete(event);
  }
}

