  }

  on(event, fn) {
    if (typeof fn !== 'function') {
      throw new TypeError('listener must be a function');
    }
    let entries = this._events.get(event);
    if (!entries) {
      entries = [];
      this._events.set(event, entries);
    }
    let entry = entries.find((e) => e.fn === fn);
    if (!entry) {
      entry = { fn };
      entries.push(entry);
