    return () => this._remove(event, entry);
  }

  off(event, fn) {
    const entries = this._events.get(event);
    if (!entries) return;
    const entry = entries.find((e) => e.fn === fn);
    if (entry) this._remove(event, entry);
  }

  emit(event, value) {
    const entries = this._events.get(event);
    if (!entries) return;
    for (const entry of entries.slice()) {
      entry.fn(value);
    }
  }

  _remove(event, entry) {
    const entries = this._events.get(event);
    if (!entries) return;
    const index = entries.indexOf(entry);
    if (index === -1) return;
    entries.splice(index, 1);
    if (entries.length === 0) this._events.delete(event);
  }
