class Emitter {
  #listeners = new Map();

  on(event, fn) {
    let entries = this.#listeners.get(event);
    if (!entries) {
      entries = [];
      this.#listeners.set(event, entries);
    }

    let entry = entries.find((candidate) => candidate.fn === fn);
    if (!entry) {
      entry = { fn };
      entries.push(entry);
    }

    return () => this.#remove(event, entry);
  }

  off(event, fn) {
    const entries = this.#listeners.get(event);
    const entry = entries?.find((candidate) => candidate.fn === fn);
    if (entry) {
      this.#remove(event, entry);
    }
  }

  emit(event, value) {
    const entries = this.#listeners.get(event);
    if (!entries) {
      return;
    }

    const snapshot = entries.map((entry) => entry.fn);
    for (const fn of snapshot) {
      fn(value);
    }
  }

  #remove(event, entry) {
    const entries = this.#listeners.get(event);
    const index = entries?.indexOf(entry) ?? -1;
    if (index === -1) {
      return;
    }

    entries.splice(index, 1);
    if (entries.length === 0) {
      this.#listeners.delete(event);
    }
  }
}

