class Emitter {
  #listeners = new Map();

  on(event, fn) {
    const list = this.#listeners.get(event) ?? [];
    const existing = list.find((entry) => entry.fn === fn);
    const entry = existing ?? { fn };
    if (!existing) this.#listeners.set(event, [...list, entry]);
    return () => this.#remove(event, entry);
  }

  off(event, fn) {
    const entry = this.#listeners.get(event)?.find((e) => e.fn === fn);
    if (entry) this.#remove(event, entry);
  }

  emit(event, value) {
    const list = this.#listeners.get(event);
    if (!list) return;
    for (const { fn } of list) fn(value);
  }

  #remove(event, entry) {
    const list = this.#listeners.get(event);
    if (!list || !list.includes(entry)) return;
    const next = list.filter((e) => e !== entry);
    if (next.length) this.#listeners.set(event, next);
    else this.#listeners.delete(event);
  }
}

