class Emitter {
  #events = new Map();

  on(event, fn) {
    if (typeof fn !== 'function') {
      throw new TypeError('listener must be a function');
    }
    let entries = this.#events.get(event);
    if (!entries) {
      entries = [];
      this.#events.set(event, entries);
    }
    if (entries.some((entry) => entry.fn === fn)) {
      return () => {};
    }
    const entry = { fn };
    entries.push(entry);
    return () => this.#remove(event, entry);
  }

  off(event, fn) {
    const entries = this.#events.get(event);
    if (!entries) return;
    const entry = entries.find((candidate) => candidate.fn === fn);
    if (entry) this.#remove(event, entry);
  }

  emit(event, value) {
    const entries = this.#events.get(event);
    if (!entries) return;
    const snapshot = entries.map((entry) => entry.fn);
    for (const fn of snapshot) {
      fn(value);
    }
  }

  #remove(event, entry) {
    const entries = this.#events.get(event);
    if (!entries) return;
    const index = entries.indexOf(entry);
    if (index === -1) return;
    entries.splice(index, 1);
    if (entries.length === 0) this.#events.delete(event);
  }
}

