class Emitter {
  #listeners = new Map();

  on(event, fn) {
    const records = this.#listeners.get(event) ?? [];
    if (records.some((record) => record.fn === fn)) return () => {};

    const record = { fn };
    records.push(record);
    this.#listeners.set(event, records);

    let subscribed = true;
    return () => {
      if (!subscribed) return;
      subscribed = false;
      this.#remove(event, record);
    };
  }

  off(event, fn) {
    const records = this.#listeners.get(event);
    const record = records?.find((candidate) => candidate.fn === fn);
    if (record) this.#remove(event, record);
  }

  emit(event, value) {
    const records = this.#listeners.get(event);
    if (!records) return;
    for (const { fn } of records.slice()) fn(value);
  }

  #remove(event, record) {
    const records = this.#listeners.get(event);
    const index = records?.indexOf(record) ?? -1;
    if (index === -1) return;
    records.splice(index, 1);
    if (records.length === 0) this.#listeners.delete(event);
  }
}

